{
  "probes": [
    {
      "obligation_id": "OB-003",
      "strategy": "example",
      "rationale": "Tests that a DENY match wins over an ALLOW match regardless of which policy is more specific (resource pattern) and regardless of which is listed first or last, directly falsifying a most-specific-wins or last-entry-wins tie-break.",
      "code": "import impl


def test_deny_wins_regardless_of_specificity_and_order():
    request = {"resource": "docs/report.txt", "action": "read"}

    # Broad DENY listed first, narrow ALLOW listed after (ALLOW is more specific and later).
    policies_broad_deny_first = [
        {"effect": "DENY", "resource": "docs/*", "action": "*"},
        {"effect": "ALLOW", "resource": "docs/report.txt", "action": "read"},
    ]
    result1 = impl.authorize(request, policies_broad_deny_first)
    assert result1 == "DENY", (
        f"expected DENY when a broad DENY precedes a narrower, later ALLOW match; got {result1!r}"
    )

    # Narrow DENY listed first, broad ALLOW listed after (ALLOW is less specific and later).
    policies_narrow_deny_first = [
        {"effect": "DENY", "resource": "docs/report.txt", "action": "read"},
        {"effect": "ALLOW", "resource": "docs/*", "action": "*"},
    ]
    result2 = impl.authorize(request, policies_narrow_deny_first)
    assert result2 == "DENY", (
        f"expected DENY when a narrow DENY precedes a broader, later ALLOW match; got {result2!r}"
    )
"
    }
  ]
}
